nextflow_process {

    name "Test Process ANTISMASH_ANTISMASHLITE"
    script "../main.nf"
    process "ANTISMASH_ANTISMASHLITE"

    tag "modules"
    tag "modules_nfcore"
    tag "antismash"
    tag "antismash/antismashlite"

    test("deprecated") {

        when {
            process {
                """
                input[0] = [ [ id:'test' ], file('sequence_input') ]
                input[1] = file('databases')
                input[2] = file('antismash_dir')
                input[3] = file('gff')
                """
            }
        }

        then {
            assertAll(
                { assert process.failed },
                { assert process.errorReport.contains("WARNING: This module has been deprecated. Please use nf-core/modules/antismash/antismash") }
            )
        }
    }
}
